const assert = require('node:assert/strict');
const {test} = require('node:test');
const {createCatalogue} = require('./catalogue.cjs');
const {createLoader} = require('./adapter.cjs');
const {quote} = require('./price.cjs');

test('caches loader results until the exact expiry measured from completion', async () => {
  let time = 0;
  let calls = 0;
  const first = {price: 12};
  const second = {price: 15};
  const catalogue = createCatalogue(async id => {
    assert.equal(id, 'a/b');
    time += 20;
    return ++calls === 1 ? first : second;
  }, () => time, 10);
  assert.strictEqual(await catalogue.get('a/b'), first);
  time = 29;
  assert.strictEqual(await catalogue.get('a/b'), first);
  assert.equal(calls, 1);
  time = 30;
  assert.strictEqual(await catalogue.get('a/b'), second);
  assert.equal(calls, 2);
});

test('preserves falsy results and keeps IDs and catalogue instances independent', async () => {
  const values = new Map([['null', null], ['false', false], ['zero', 0], ['', ''], ['__proto__', undefined]]);
  const loaded = [];
  const load = async id => {
    loaded.push(id);
    return values.get(id);
  };
  const catalogue = createCatalogue(load, () => 0, 10);
  for (const [id, value] of values) {
    assert.strictEqual(await catalogue.get(id), value);
    assert.strictEqual(await catalogue.get(id), value);
  }
  assert.deepEqual(loaded, [...values.keys()]);
  const another = createCatalogue(load, () => 0, 10);
  assert.equal(await another.get('zero'), 0);
  assert.deepEqual(loaded, [...values.keys(), 'zero']);
});

test('propagates original failures without caching them or serving expired data', async () => {
  let time = 0;
  let calls = 0;
  const error = new Error('unavailable');
  const catalogue = createCatalogue(async () => {
    calls++;
    if (calls === 1 || calls === 3 || calls === 4) throw error;
    return calls;
  }, () => time, 10);
  await assert.rejects(catalogue.get('item'), failure => failure === error);
  assert.equal(await catalogue.get('item'), 2);
  time = 10;
  await assert.rejects(catalogue.get('item'), failure => failure === error);
  await assert.rejects(catalogue.get('item'), failure => failure === error);
  assert.equal(await catalogue.get('item'), 5);
  assert.equal(await catalogue.get('item'), 5);
  assert.equal(calls, 5);
});

test('preserves the loader adapter and price caller behavior', async () => {
  const paths = [];
  const value = {price: 7};
  const catalogue = createCatalogue(createLoader(async path => {
    paths.push(path);
    return value;
  }), () => 0, 10);
  assert.deepEqual(await quote(catalogue, 'a /?'), {id: 'a /?', value});
  assert.deepEqual(await quote(catalogue, 'a /?'), {id: 'a /?', value});
  assert.deepEqual(paths, ['/items/a%20%2F%3F']);
});

