const assert = require('node:assert/strict');
const http = require('node:http');
const {once} = require('node:events');
const {test} = require('node:test');
const {createServer} = require('./server.cjs');
const {start} = require('./app.cjs');

async function request(server, body, method = 'POST', path = '/notes') {
  return new Promise((resolve, reject) => {
    const req = http.request({host: '127.0.0.1', port: server.address().port, method, path}, res => {
      let raw = '';
      res.setEncoding('utf8');
      res.on('data', chunk => { raw += chunk; });
      res.on('end', () => resolve({status: res.statusCode, type: res.headers['content-type'], body: JSON.parse(raw)}));
    });
    req.on('error', reject);
    if (Array.isArray(body)) {
      req.write(body[0]);
      setImmediate(() => req.end(body[1]));
    } else {
      req.end(body);
    }
  });
}

test('valid notes await persistence once and preserve text and IDs', async t => {
  const calls = [];
  const ids = [0, '', 'saved'];
  const server = createServer(async text => {
    calls.push(text);
    await new Promise(resolve => setImmediate(resolve));
    return ids[calls.length - 1];
  });
  assert.equal(server.listening, false);
  server.listen(0, '127.0.0.1');
  await once(server, 'listening');
  t.after(() => new Promise(resolve => server.close(resolve)));
  for (const [index, text] of ['', 'hello', '雪😀'].entries()) {
    assert.deepEqual(await request(server, index === 2
      ? [Buffer.from(JSON.stringify({text, ignored: true})).subarray(0, 10), Buffer.from(JSON.stringify({text, ignored: true})).subarray(10)]
      : JSON.stringify({text, ignored: true})), {
      status: 201, type: 'application/json', body: {id: ids[index], text}
    });
  }
  assert.deepEqual(calls, ['', 'hello', '雪😀']);
});

test('invalid JSON and note shapes never save', async t => {
  let calls = 0;
  const server = start(() => { calls++; });
  await once(server, 'listening');
  t.after(() => new Promise(resolve => server.close(resolve)));
  for (const raw of ['', '{', 'null', '[]', '["text"]', '{}', '"text"', '1', 'true', '{"text":null}', '{"text":0}', '{"text":false}', '{"text":[]}', '{"text":{}}']) {
    assert.deepEqual(await request(server, raw), {
      status: 400, type: 'application/json', body: {error: 'invalid note'}
    });
  }
  assert.equal(calls, 0);
});

test('save rejections return 500 including falsy rejection values', async t => {
  let calls = 0;
  const server = start(async () => { calls++; throw undefined; });
  await once(server, 'listening');
  t.after(() => new Promise(resolve => server.close(resolve)));
  assert.deepEqual(await request(server, '{"text":"note"}'), {
    status: 500, type: 'application/json', body: {error: 'save failed'}
  });
  assert.equal(calls, 1);
});

test('other methods and paths return 404 without saving', async t => {
  let calls = 0;
  const server = start(() => { calls++; });
  await once(server, 'listening');
  t.after(() => new Promise(resolve => server.close(resolve)));
  for (const [method, path] of [['GET', '/notes'], ['POST', '/other'], ['POST', '/notes?x=1'], ['PUT', '/notes']]) {
    assert.deepEqual(await request(server, '{', method, path), {
      status: 404, type: 'application/json', body: {error: 'not found'}
    });
  }
  assert.equal(calls, 0);
});

