const assert = require('node:assert/strict');
const {execFileSync} = require('node:child_process');
const {createBasket} = require('./basket.cjs');

const initial = [{sku: 'tea', price: 250, quantity: 2}, {sku: 'cake', price: 400, quantity: 1}];
const basket = createBasket(initial);
assert.equal(basket.count, 3);
assert.equal(basket.total, 900);
initial[0].quantity = 20;
initial.push({sku: 'extra', price: 1, quantity: 1});
assert.equal(basket.count, 3);

const receipt = basket.receipt;
const snapshot = receipt();
basket.set('tea', 100, 1);
assert.deepEqual(basket.receipt(), {
  items: [{sku: 'tea', price: 100, quantity: 1}, {sku: 'cake', price: 400, quantity: 1}],
  count: 2, total: 500,
});
assert.equal(snapshot.count, 3);
assert.equal(snapshot.total, 900);
assert.equal(snapshot.items[0].quantity, 2);
snapshot.items[0].price = 999;
snapshot.items.push({sku: 'fake', price: 999, quantity: 1});
assert.equal(basket.total, 500);

basket.set('', 0, 3);
assert.equal(basket.count, 5);
assert.equal(basket.total, 500);
basket.remove('tea');
assert.deepEqual(basket.receipt(), {
  items: [{sku: 'cake', price: 400, quantity: 1}, {sku: '', price: 0, quantity: 3}],
  count: 4, total: 400,
});
basket.remove('missing');
assert.equal(basket.count, 4);
basket.set('tea', 250, 2);
assert.deepEqual(basket.receipt().items.map(row => row.sku), ['cake', '', 'tea']);

const replacement = [{sku: 'new', price: 10, quantity: 4}];
basket.reset(replacement);
replacement[0].price = 500;
replacement.length = 0;
assert.deepEqual(basket.receipt(), {items: [{sku: 'new', price: 10, quantity: 4}], count: 4, total: 40});
const independent = createBasket();
independent.set('other', 1, 1);
basket.reset();
assert.deepEqual(basket.receipt(), {items: [], count: 0, total: 0});
assert.deepEqual(independent.receipt(), {items: [{sku: 'other', price: 1, quantity: 1}], count: 1, total: 1});
assert.deepEqual(createBasket([]).receipt(), {items: [], count: 0, total: 0});
assert.deepEqual(JSON.parse(execFileSync(process.execPath, [require.resolve('./demo.cjs')], {encoding: 'utf8'})), {
  items: [{sku: 'tea', price: 250, quantity: 2}, {sku: 'cake', price: 400, quantity: 1}],
  count: 3, total: 900,
});

