exports.createCatalogue = (load, now, ttl) => {
  const cache = new Map();
  return {
    async get(id) {
      const entry = cache.get(id);
      if (entry && now() < entry.expiresAt) return entry.value;
      const value = await load(id);
      cache.set(id, { value, expiresAt: now() + ttl });
      return value;
    }
  };
};

