const assert = require('node:assert/strict');
const { test } = require('node:test');
const { createCatalogue } = require('./catalogue.cjs');
const { createLoader } = require('./adapter.cjs');
const { quote } = require('./price.cjs');

test('caches through load completion and refreshes at exact expiry', async () => {
  let time = 0;
  let calls = 0;
  const catalogue = createCatalogue(async () => {
    calls++;
    time += 20;
    return { calls };
  }, () => time, 10);
  const first = await catalogue.get('a');
  time = 29;
  assert.strictEqual(await catalogue.get('a'), first);
  assert.equal(calls, 1);
  time = 30;
  assert.deepEqual(await catalogue.get('a'), { calls: 2 });
});

test('preserves and caches every falsy result', async () => {
  for (const value of [null, false, 0, '', undefined]) {
    let calls = 0;
    const catalogue = createCatalogue(async () => {
      calls++;
      return value;
    }, () => 0, 10);
    assert.strictEqual(await catalogue.get('a'), value);
    assert.strictEqual(await catalogue.get('a'), value);
    assert.equal(calls, 1);
  }
});

test('propagates original failures and never serves stale values after refresh failure', async () => {
  let time = 0;
  let calls = 0;
  const failure = new Error('load failed');
  const catalogue = createCatalogue(async () => {
    calls++;
    if (calls === 1 || calls === 3 || calls === 4) throw failure;
    return calls;
  }, () => time, 10);
  await assert.rejects(catalogue.get('a'), error => error === failure);
  assert.equal(await catalogue.get('a'), 2);
  time = 10;
  await assert.rejects(catalogue.get('a'), error => error === failure);
  await assert.rejects(catalogue.get('a'), error => error === failure);
  assert.equal(await catalogue.get('a'), 5);
  assert.equal(await catalogue.get('a'), 5);
  assert.equal(calls, 5);
});

test('keeps string IDs and instances independent with adapter and price caller', async () => {
  const urls = [];
  const loader = createLoader(async url => {
    urls.push(url);
    return { url, call: urls.length };
  });
  const first = createCatalogue(loader, () => 0, 10);
  const second = createCatalogue(loader, () => 0, 10);
  for (const id of ['a/b', '', '__proto__', 'constructor']) {
    const result = await quote(first, id);
    assert.equal(result.id, id);
    assert.equal(result.value.url, '/items/' + encodeURIComponent(id));
    assert.strictEqual((await quote(first, id)).value, result.value);
  }
  const other = await second.get('a/b');
  assert.notStrictEqual(other, await first.get('a/b'));
  assert.equal(urls.length, 5);
});

