const assert = require('node:assert/strict');
const http = require('node:http');
const {once} = require('node:events');
const {test} = require('node:test');
const {createServer} = require('./server.cjs');
const {start} = require('./app.cjs');

async function request(server, method, path, chunks) {
  const req = http.request({host: '127.0.0.1', port: server.address().port, method, path});
  const response = once(req, 'response');
  for (const chunk of chunks) {
    req.write(chunk);
    await new Promise(resolve => setImmediate(resolve));
  }
  req.end();
  const [res] = await response;
  res.setEncoding('utf8');
  let raw = '';
  for await (const chunk of res) raw += chunk;
  assert.equal(res.headers['content-type'], 'application/json');
  return {status: res.statusCode, body: JSON.parse(raw)};
}

test('valid notes await one save and preserve text and IDs', async t => {
  const calls = [];
  const ids = [0, '', 'saved'];
  const server = createServer(async text => {
    calls.push(text);
    await new Promise(resolve => setImmediate(resolve));
    return ids[calls.length - 1];
  });
  assert.equal(server.listening, false);
  t.after(() => new Promise(resolve => server.close(resolve)));
  server.listen(0, '127.0.0.1');
  await once(server, 'listening');
  for (const [index, text] of ['', 'hello', 'café 🌍'].entries()) {
    const raw = Buffer.from(JSON.stringify({text, ignored: true}));
    const chunks = [...raw].map(byte => Buffer.from([byte]));
    assert.deepEqual(await request(server, 'POST', '/notes', chunks), {
      status: 201, body: {id: ids[index], text}
    });
    assert.deepEqual(calls, ['', 'hello', 'café 🌍'].slice(0, index + 1));
  }
});

test('invalid JSON and invalid note shapes never save', async t => {
  const calls = [];
  const server = start(text => calls.push(text));
  t.after(() => new Promise(resolve => server.close(resolve)));
  await once(server, 'listening');
  for (const raw of ['', '{', 'null', '[]', '["hello"]', '{}', '"hello"', '0', 'true',
    '{"text":null}', '{"text":0}', '{"text":false}', '{"text":[]}', '{"text":{}}']) {
    assert.deepEqual(await request(server, 'POST', '/notes', [raw]), {
      status: 400, body: {error: 'invalid note'}
    }, raw);
  }
  assert.deepEqual(calls, []);
});

test('save rejection is a server error', async t => {
  let calls = 0;
  const server = start(async text => {
    calls++;
    assert.equal(text, 'hello');
    throw new Error('database unavailable');
  });
  t.after(() => new Promise(resolve => server.close(resolve)));
  await once(server, 'listening');
  assert.deepEqual(await request(server, 'POST', '/notes', ['{"text":"hello"}']), {
    status: 500, body: {error: 'save failed'}
  });
  assert.equal(calls, 1);
});

test('other method and path combinations return not found without saving', async t => {
  const calls = [];
  const server = start(text => calls.push(text));
  t.after(() => new Promise(resolve => server.close(resolve)));
  await once(server, 'listening');
  for (const [method, path] of [['GET', '/notes'], ['PUT', '/notes'], ['POST', '/other'],
    ['POST', '/notes/'], ['POST', '/notes?x=1']]) {
    assert.deepEqual(await request(server, method, path, []), {
      status: 404, body: {error: 'not found'}
    });
  }
  assert.deepEqual(calls, []);
});

