exports.saveDraft = async (draft, {store,audit}) => {
  let result;
  try {
    result = await store.write(draft);
  } catch (error) {
    await audit({type:'failed',id:draft.id});
    throw error;
  }
  await audit({type:'saved',id:draft.id});
  return result;
};

