+          if (auditMode === 'reject') return Promise.reject(auditError);
+          return auditMode === 'resolve' ? Promise.resolve() : undefined;
+        },
+      });
+      if (auditFails || writeFails) {
+        await assert.rejects(operation, error => error === (auditFails ? auditError : writeError));
+      } else {
+        assert.equal(await operation, result);
+      }
+      assert.deepEqual(calls, ['write', {type: writeFails ? 'failed' : 'saved', id: 0}]);
+    });
+  }
+}
+
+for (const fails of [false, true]) {
+  test(`awaits write and ${fails ? 'failed' : 'saved'} audit`, async () => {
+    const write = Promise.withResolvers();
+    const audit = Promise.withResolvers();
+    const events = [];
+    const writeError = new Error('write');
+    let settled = false;
+    const operation = saveDraft({id: 'draft'}, {
+      store: {write: () => write.promise},
+      audit: event => { events.push(event); return audit.promise; },
+    });
+    const observed = operation.then(
+      value => { settled = true; return value; },
+      error => { settled = true; throw error; },
+    );
+    assert.deepEqual(events, []);
+    if (fails) write.reject(writeError);
+    else write.resolve('result');
+    await Promise.resolve();
+    assert.deepEqual(events, [{type: fails ? 'failed' : 'saved', id: 'draft'}]);
+    assert.equal(settled, false);
+    audit.resolve();
+    if (fails) await assert.rejects(observed, error => error === writeError);
+    else assert.equal(await observed, 'result');
+  });
+}
+
+test('store serializes once and waits for writeFile', async () => {
+  const pending = Promise.withResolvers();
+  const draft = {id: 'draft', content: ''};
+  const calls = [];
+  const store = createStore((...args) => { calls.push(args); return pending.promise; });
+  let settled = false;
+  const operation = store.write(draft).then(value => { settled = true; return value; });
+  await Promise.resolve();
+  assert.equal(settled, false);
+  assert.deepEqual(calls, [['draft.json', JSON.stringify(draft), 'utf8']]);
+  pending.resolve();
+  assert.equal(await operation, draft.id);
+});

