const http = require('node:http');
exports.createServer = save => http.createServer(async (req, res) => {
  res.setHeader('content-type', 'application/json');
  if (req.method !== 'POST' || req.url !== '/notes') {res.writeHead(404); res.end(JSON.stringify({error: 'not found'})); return;}
  req.setEncoding('utf8');
  let raw = ''; for await (const chunk of req) raw += chunk;
  let note;
  try {
    note = JSON.parse(raw);
  } catch {
    res.writeHead(400); res.end(JSON.stringify({error: 'invalid note'})); return;
  }
  if (note === null || typeof note !== 'object' || Array.isArray(note) || typeof note.text !== 'string') {
    res.writeHead(400); res.end(JSON.stringify({error: 'invalid note'})); return;
  }
  const {text} = note;
  let id;
  try {
    id = await save(text);
  } catch {
    res.writeHead(500); res.end(JSON.stringify({error: 'save failed'})); return;
  }
  res.writeHead(201); res.end(JSON.stringify({id, text}));
});

