const assert = require('node:assert/strict');
const http = require('node:http');
const {once} = require('node:events');
const {test} = require('node:test');
const {createServer} = require('./server.cjs');
const {start} = require('./app.cjs');

async function request(server, body, method = 'POST', path = '/notes') {
  return new Promise((resolve, reject) => {
    const req = http.request({host: '127.0.0.1', port: server.address().port, method, path}, res => {
      let raw = '';
      res.setEncoding('utf8');
      res.on('data', chunk => { raw += chunk; });
      res.on('end', () => resolve({status: res.statusCode, type: res.headers['content-type'], body: JSON.parse(raw)}));
    });
    req.on('error', reject);
    for (const chunk of Array.isArray(body) ? body : [body]) req.write(chunk);
    req.end();
  });
}

async function listen(t, save) {
  const server = createServer(save);
  assert.equal(server.listening, false);
  server.listen(0, '127.0.0.1');
  await once(server, 'listening');
  t.after(() => new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve())));
  return server;
}

function response(status, body) {
  return {status, type: 'application/json', body};
}

test('saves only valid text once, awaits persistence and preserves IDs', async t => {
  const calls = [];
  const ids = [0, '', 'saved'];
  const server = await listen(t, async text => {
    calls.push(text);
    await new Promise(resolve => setImmediate(resolve));
    return ids.shift();
  });
  for (const [text, id] of [['', 0], ['hello', '']]) {
    assert.deepEqual(await request(server, JSON.stringify({text, ignored: true})), response(201, {id, text}));
  }
  const body = Buffer.from(JSON.stringify({text: '😀 café'}));
  const split = body.indexOf(Buffer.from('😀')) + 1;
  assert.deepEqual(await request(server, [body.subarray(0, split), body.subarray(split)]), response(201, {id: 'saved', text: '😀 café'}));
  assert.deepEqual(calls, ['', 'hello', '😀 café']);
});

test('rejects invalid notes without saving', async t => {
  let calls = 0;
  const server = await listen(t, () => { calls++; return 1; });
  for (const body of ['', '{', 'null', '[]', '["text"]', '{}', '{"text":null}', '{"text":1}', '{"text":false}', '{"text":{}}', '{"text":[]}', '"hello"', '42', 'true']) {
    await t.test(body || 'empty body', async () => {
      assert.deepEqual(await request(server, body), response(400, {error: 'invalid note'}));
    });
  }
  assert.equal(calls, 0);
});

test('save failures return 500 with no retry', async t => {
  let calls = 0;
  const server = await listen(t, async () => { calls++; throw new Error('private details'); });
  assert.deepEqual(await request(server, '{"text":"hello"}'), response(500, {error: 'save failed'}));
  assert.equal(calls, 1);
});

test('other methods and paths return 404 without saving', async t => {
  let calls = 0;
  const server = await listen(t, () => { calls++; });
  for (const [method, path] of [['GET', '/notes'], ['PUT', '/notes'], ['POST', '/other'], ['POST', '/notes?x=1'], ['POST', '/notes/']]) {
    assert.deepEqual(await request(server, '{}', method, path), response(404, {error: 'not found'}));
  }
  assert.equal(calls, 0);
});

test('app start remains usable with its default port', async t => {
  const server = start(async () => 7);
  await once(server, 'listening');
  t.after(() => new Promise(resolve => server.close(resolve)));
  assert.deepEqual(await request(server, '{"text":"app"}'), response(201, {id: 7, text: 'app'}));
});

