const assert = require('node:assert/strict');
const {test} = require('node:test');
const http = require('node:http');
const {once} = require('node:events');
const {createServer} = require('./server.cjs');
const {start} = require('./app.cjs');

async function request(server, body, method = 'POST', path = '/notes') {
  return new Promise((resolve, reject) => {
    const req = http.request({hostname: '127.0.0.1', port: server.address().port, method, path}, res => {
      let raw = '';
      res.setEncoding('utf8');
      res.on('data', chunk => { raw += chunk; });
      res.on('end', () => resolve({status: res.statusCode, type: res.headers['content-type'], body: JSON.parse(raw)}));
    });
    req.on('error', reject);
    if (Array.isArray(body)) {
      req.write(body[0], () => setTimeout(() => req.end(body[1]), 10));
    } else {
      req.end(body);
    }
  });
}

async function listen(t, save) {
  const server = createServer(save);
  assert.equal(server.listening, false);
  server.listen(0, '127.0.0.1');
  await once(server, 'listening');
  t.after(() => new Promise(resolve => server.close(resolve)));
  return server;
}

test('valid notes preserve text and falsy IDs and await persistence once', async t => {
  const calls = [];
  const ids = [0, '', 'saved'];
  const server = await listen(t, async text => {
    calls.push(text);
    await new Promise(resolve => setImmediate(resolve));
    return ids[calls.length - 1];
  });
  const texts = ['', 'hello', '雪🙂'];
  for (let i = 0; i < texts.length; i++) {
    assert.deepEqual(await request(server, JSON.stringify({text: texts[i], ignored: true})), {
      status: 201, type: 'application/json', body: {id: ids[i], text: texts[i]}
    });
  }
  assert.deepEqual(calls, texts);
});

test('invalid bodies never reach persistence', async t => {
  let calls = 0;
  const server = await listen(t, () => { calls++; return 'id'; });
  for (const body of ['', '{', 'null', '[]', '{}', '{"text":null}', '{"text":0}', '{"text":false}', '{"text":[]}', '"text"']) {
    assert.deepEqual(await request(server, body), {
      status: 400, type: 'application/json', body: {error: 'invalid note'}
    });
  }
  assert.equal(calls, 0);
});

test('persistence rejection returns a server error and permits the next request', async t => {
  let calls = 0;
  const server = await listen(t, async () => {
    calls++;
    if (calls === 1) throw undefined;
    return 2;
  });
  assert.deepEqual(await request(server, '{"text":"a"}'), {
    status: 500, type: 'application/json', body: {error: 'save failed'}
