const assert = require('node:assert/strict');
const {buildReport} = require('./report.cjs');
const {formatRow} = require('./format.cjs');

const rows = Object.freeze([
  Object.freeze({label: '', amount: 0}),
  Object.freeze({label: 'Debit', amount: -2.5}),
  Object.freeze({label: 'Credit', amount: 4}),
  Object.freeze({label: 'Tiny', amount: 1e-7}),
]);

assert.equal(formatRow(rows[0]), ': 0');
assert.equal(formatRow(rows[1]), 'Debit: -2.5');
assert.equal(formatRow(rows[3]), 'Tiny: 1e-7');
assert.deepEqual(buildReport(rows, ''), {
  title: '',
  count: 4,
  total: 1.5000001,
  lines: [': 0', 'Debit: -2.5', 'Credit: 4', 'Tiny: 1e-7'],
});
assert.deepEqual(buildReport([]), {title: 'Report', count: 0, total: 0, lines: []});
assert.equal(buildReport(rows, undefined).title, 'Report');
assert.equal(buildReport(rows, 'Ledger').title, 'Ledger');

const first = buildReport(rows);
const second = buildReport(rows);
assert.notStrictEqual(first, second);
assert.notStrictEqual(first.lines, second.lines);
first.title = 'Changed';
first.lines.push('Extra');
assert.deepEqual(second, buildReport(rows));
assert.equal(rows.length, 4);
assert.deepEqual(rows[0], {label: '', amount: 0});
const emptyFirst = buildReport([]);
const emptySecond = buildReport([]);
assert.notStrictEqual(emptyFirst, emptySecond);
assert.notStrictEqual(emptyFirst.lines, emptySecond.lines);

