exports.createCatalogue = (load, now, ttl) => {
  const entries = new Map();
  return {
    async get(id) {
      const entry = entries.get(id);
      if (entry && now() < entry.expiresAt) return entry.value;
      const value = await load(id);
      entries.set(id, {value, expiresAt: now() + ttl});
      return value;
    }
  };
};

