const assert = require('node:assert/strict');
const {createCatalogue} = require('./catalogue.cjs');
const {createLoader} = require('./adapter.cjs');
const {quote} = require('./price.cjs');

(async () => {
  let time = 0;
  const calls = [];
  const catalogue = createCatalogue(async id => {
    calls.push(id);
    time += 5;
    return {id, version: calls.length};
  }, () => time, 10);
  const first = await catalogue.get('a');
  time = 14;
  assert.strictEqual(await catalogue.get('a'), first);
  time = 15;
  const refreshed = await catalogue.get('a');
  assert.notStrictEqual(refreshed, first);
  assert.deepEqual(calls, ['a', 'a']);
  const other = await catalogue.get('__proto__');
  assert.equal(other.id, '__proto__');
  assert.strictEqual(await catalogue.get('a'), refreshed);

  for (const value of [null, false, 0, '', undefined]) {
    let loads = 0;
    const cache = createCatalogue(async () => { loads++; return value; }, () => 0, 10);
    assert.strictEqual(await cache.get('id'), value);
    assert.strictEqual(await cache.get('id'), value);
    assert.equal(loads, 1);
  }

  let fail = true;
  let loads = 0;
  time = 0;
  const error = new Error('load failed');
  const recovering = createCatalogue(async () => {
    loads++;
    if (fail) throw error;
    return loads;
  }, () => time, 10);
  await assert.rejects(recovering.get('id'), actual => actual === error);
  fail = false;
  assert.equal(await recovering.get('id'), 2);
  time = 10;
  fail = true;
  await assert.rejects(recovering.get('id'), actual => actual === error);
  await assert.rejects(recovering.get('id'), actual => actual === error);
  fail = false;
  assert.equal(await recovering.get('id'), 5);

  const independent = createCatalogue(async () => 'independent', () => 0, 10);
  assert.equal(await independent.get('a'), 'independent');
  const paths = [];
  const prices = createCatalogue(createLoader(async path => { paths.push(path); return 0; }), () => 0, 10);
  assert.deepEqual(await quote(prices, 'a/b'), {id: 'a/b', value: 0});
  assert.deepEqual(await quote(prices, 'a/b'), {id: 'a/b', value: 0});
  assert.deepEqual(paths, ['/items/a%2Fb']);
})().catch(error => {
  console.error(error);
  process.exitCode = 1;
});

