const assert = require('node:assert/strict');
const {createCatalogue} = require('./catalogue.cjs');
const {createLoader} = require('./adapter.cjs');
const {quote} = require('./price.cjs');

(async () => {
  let time = 0;
  let calls = 0;
  const first = {price: 12};
  const catalogue = createCatalogue(async id => {
    assert.equal(id, 'item');
    calls++;
    time += 20;
    return calls === 1 ? first : {price: 15};
  }, () => time, 10);
  assert.strictEqual(await catalogue.get('item'), first);
  time = 29;
  assert.strictEqual(await catalogue.get('item'), first);
  assert.equal(calls, 1);
  time = 30;
  assert.deepEqual(await catalogue.get('item'), {price: 15});
  assert.equal(calls, 2);

  for (const value of [null, false, 0, '', undefined]) {
    let loads = 0;
    const falsy = createCatalogue(async () => { loads++; return value; }, () => 0, 10);
    assert.strictEqual(await falsy.get('key'), value);
    assert.strictEqual(await falsy.get('key'), value);
    assert.equal(loads, 1);
  }

  const ids = [];
  const independent = createCatalogue(async id => { ids.push(id); return id; }, () => 0, 10);
  for (const id of ['a', 'b', '__proto__', 'constructor', '']) {
    assert.equal(await independent.get(id), id);
    assert.equal(await independent.get(id), id);
  }
  assert.deepEqual(ids, ['a', 'b', '__proto__', 'constructor', '']);
  const another = createCatalogue(async () => 'other', () => 0, 10);
  assert.equal(await another.get('a'), 'other');

  let attempts = 0;
  let clock = 0;
  const error = new Error('load failed');
  const refresh = createCatalogue(async () => {
    attempts++;
    if (attempts === 1 || attempts === 3 || attempts === 4) throw error;
    return attempts;
  }, () => clock, 10);
  await assert.rejects(refresh.get('x'), failure => failure === error);
  assert.equal(await refresh.get('x'), 2);
  clock = 10;
  await assert.rejects(refresh.get('x'), failure => failure === error);
  await assert.rejects(refresh.get('x'), failure => failure === error);
  assert.equal(await refresh.get('x'), 5);
  assert.equal(await refresh.get('x'), 5);
  assert.equal(attempts, 5);

  const urls = [];
  const priced = createCatalogue(createLoader(async url => {
    urls.push(url);
    return 0;
  }), () => 0, 10);
  assert.deepEqual(await quote(priced, 'a/b ?'), {id: 'a/b ?', value: 0});
  assert.deepEqual(await quote(priced, 'a/b ?'), {id: 'a/b ?', value: 0});
  assert.deepEqual(urls, ['/items/a%2Fb%20%3F']);
})().catch(error => {
  console.error(error);
  process.exitCode = 1;
});

