assert.deepEqual(buildReport(input), {
  title: 'Report', count: 2, total: 3, lines: ['updated: 4', 'new: -1'],
});
const empty = buildReport([]);
const nextEmpty = buildReport([]);
assert.notStrictEqual(empty, nextEmpty);
assert.notStrictEqual(empty.lines, nextEmpty.lines);

