const assert = require('node:assert/strict');
const {test} = require('node:test');
const {setImmediate} = require('node:timers/promises');
const {saveDraft} = require('./service.cjs');
const {createStore} = require('./store.cjs');

const outcomes = ['return', 'resolve', 'throw', 'reject'];

for (const writeOutcome of outcomes) {
  for (const auditOutcome of outcomes) {
    test(`write ${writeOutcome}, audit ${auditOutcome}`, async () => {
      const draft = {id: 'draft'};
      const result = {};
      const writeError = new Error('write');
      const auditError = new Error('audit');
      const calls = [];
      const writeFails = ['throw', 'reject'].includes(writeOutcome);
      const auditFails = ['throw', 'reject'].includes(auditOutcome);
      const operation = saveDraft(draft, {
        store: {
          write(received) {
            assert.strictEqual(received, draft);
            calls.push('write');
            if (writeOutcome === 'throw') throw writeError;
            if (writeOutcome === 'reject') return Promise.reject(writeError);
            return writeOutcome === 'resolve' ? Promise.resolve(result) : result;
          },
        },
        audit(event) {
          calls.push(event);
          if (auditOutcome === 'throw') throw auditError;
          if (auditOutcome === 'reject') return Promise.reject(auditError);
          return auditOutcome === 'resolve' ? Promise.resolve() : undefined;
        },
      });
      if (auditFails || writeFails) {
        await assert.rejects(operation, error => error === (auditFails ? auditError : writeError));
      } else {
        assert.strictEqual(await operation, result);
      }
      assert.deepEqual(calls, ['write', {type: writeFails ? 'failed' : 'saved', id: draft.id}]);
    });
  }
}

for (const writeFails of [false, true]) {
  test(`awaits write and ${writeFails ? 'failed' : 'saved'} audit`, async () => {
    const write = Promise.withResolvers();
    const audit = Promise.withResolvers();
    const events = [];
    const result = {};
    const writeError = new Error('write');
    let settled = false;
    const operation = saveDraft({id: 'pending'}, {
      store: {write: () => write.promise},
      audit(event) {
        events.push(event);
        return audit.promise;
      },
    });
    operation.then(() => { settled = true; }, () => { settled = true; });
    assert.deepEqual(events, []);
    if (writeFails) write.reject(writeError);
    else write.resolve(result);
    await setImmediate();
    assert.deepEqual(events, [{type: writeFails ? 'failed' : 'saved', id: 'pending'}]);
    assert.equal(settled, false);
    audit.resolve();
    if (writeFails) await assert.rejects(operation, error => error === writeError);
    else assert.strictEqual(await operation, result);
  });
}

test('store adapter writes serialized draft and awaits completion', async () => {
  const write = Promise.withResolvers();
  const draft = {id: 'adapter', text: 'hello'};
  const calls = [];
  const store = createStore((...args) => {
    calls.push(args);
    return write.promise;
  });
  let settled = false;
  const operation = store.write(draft);
  operation.then(() => { settled = true; });
  await setImmediate();
  assert.equal(settled, false);
  assert.deepEqual(calls, [['adapter.json', JSON.stringify(draft), 'utf8']]);
  write.resolve('ignored');
  assert.equal(await operation, draft.id);
});

