const assert = require('node:assert/strict');
const {test} = require('node:test');
const {setImmediate} = require('node:timers/promises');
const {saveDraft} = require('./service.cjs');
const {createStore} = require('./store.cjs');

const draft = {id: 'draft-1', text: 'hello'};

test('saveDraft preserves results, events, and dependency failures', async () => {
  for (const writeMode of ['return', 'resolve', 'throw', 'reject']) {
    for (const auditMode of ['return', 'resolve', 'throw', 'reject']) {
      const result = {stored: true};
      const writeError = new Error('write');
      const auditError = new Error('audit');
      const calls = [];
      const writeFailed = ['throw', 'reject'].includes(writeMode);
      const auditFailed = ['throw', 'reject'].includes(auditMode);
      const operation = saveDraft(draft, {
        store: {
          write(value) {
            assert.strictEqual(value, draft);
            calls.push('write');
            if (writeMode === 'throw') throw writeError;
            if (writeMode === 'reject') return Promise.reject(writeError);
            return writeMode === 'resolve' ? Promise.resolve(result) : result;
          },
        },
        audit(event) {
          calls.push(event);
          if (auditMode === 'throw') throw auditError;
          if (auditMode === 'reject') return Promise.reject(auditError);
          return auditMode === 'resolve' ? Promise.resolve() : undefined;
        },
      });
      if (auditFailed || writeFailed) {
        await assert.rejects(operation, error => error === (auditFailed ? auditError : writeError));
      } else {
        assert.strictEqual(await operation, result);
      }
      assert.deepEqual(calls, ['write', {type: writeFailed ? 'failed' : 'saved', id: draft.id}]);
    }
  }
});

test('saveDraft waits for the write and required audit on both paths', async () => {
  for (const writeFailed of [false, true]) {
    const result = {};
    const writeError = new Error('write');
    let finishWrite;
    let finishAudit;
    let auditEvent;
    let settled = false;
    const operation = saveDraft(draft, {
      store: {write: () => new Promise((resolve, reject) => {
        finishWrite = () => writeFailed ? reject(writeError) : resolve(result);
      })},
      audit: event => {
        auditEvent = event;
        return new Promise(resolve => { finishAudit = resolve; });
      },
    });
    operation.then(() => { settled = true; }, () => { settled = true; });
    assert.equal(auditEvent, undefined);
    finishWrite();
    await setImmediate();
    assert.deepEqual(auditEvent, {type: writeFailed ? 'failed' : 'saved', id: draft.id});
    assert.equal(settled, false);
    finishAudit();
    if (writeFailed) await assert.rejects(operation, error => error === writeError);
    else assert.strictEqual(await operation, result);
  }
});

test('createStore serializes the draft and waits before returning its id', async () => {
  const calls = [];
  let finishWrite;
  let settled = false;
  const store = createStore((...args) => {
    calls.push(args);
    return new Promise(resolve => { finishWrite = resolve; });
  });
  const operation = store.write(draft);
  operation.then(() => { settled = true; });
  assert.deepEqual(calls, [[draft.id + '.json', JSON.stringify(draft), 'utf8']]);
  await setImmediate();
  assert.equal(settled, false);
  finishWrite();
  assert.equal(await operation, draft.id);
});

