const assert = require('node:assert/strict');
const {buildReport} = require('./report.cjs');
const {formatRow} = require('./format.cjs');

assert.deepEqual(buildReport([]), {
  title: 'Report', count: 0, total: 0, lines: []
});
assert.equal(buildReport([], undefined).title, 'Report');

const rows = Object.freeze([
  Object.freeze({label: '', amount: 0}),
  Object.freeze({label: 'refund', amount: -2.5}),
  Object.freeze({label: 'sale', amount: 7.25}),
  Object.freeze({label: 'sale', amount: 1})
]);
const report = buildReport(rows, '');
assert.deepEqual(report, {
  title: '', count: 4, total: 5.75,
  lines: [': 0', 'refund: -2.5', 'sale: 7.25', 'sale: 1']
});
assert.equal(buildReport(rows, 'Sales').title, 'Sales');
assert.equal(formatRow({label: 'small', amount: 1e-7}), 'small: 1e-7');
assert.equal(formatRow({label: '', amount: -0}), ': 0');

const next = buildReport(rows, '');
assert.notStrictEqual(next, report);
assert.notStrictEqual(next.lines, report.lines);
report.lines.push('extra');
report.title = 'changed';
assert.deepEqual(buildReport(rows, ''), next);
const empty = buildReport([]);
assert.notStrictEqual(buildReport([]), empty);
assert.notStrictEqual(buildReport([]).lines, empty.lines);

const ownedRows = [{label: 'original', amount: 3}];
const ownedReport = buildReport(ownedRows);
ownedRows[0].label = 'changed';
ownedRows[0].amount = 9;
ownedRows.push({label: 'new', amount: 1});
assert.deepEqual(ownedReport, {
  title: 'Report', count: 1, total: 3, lines: ['original: 3']
});

