'use strict';

const assert = require('node:assert/strict');
const {buildReport} = require('./report.cjs');
const {formatRow} = require('./format.cjs');

const rows = Object.freeze([
  Object.freeze({label: 'credit', amount: 12.5}),
  Object.freeze({label: '', amount: 0}),
  Object.freeze({label: 'credit', amount: -2.5}),
]);
assert.deepEqual(buildReport(rows, ''), {
  title: '',
  count: 3,
  total: 10,
  lines: ['credit: 12.5', ': 0', 'credit: -2.5'],
});
assert.deepEqual(buildReport([], undefined), {
  title: 'Report', count: 0, total: 0, lines: [],
});
assert.equal(buildReport(rows).title, 'Report');
assert.equal(buildReport(rows, 'Ledger').title, 'Ledger');
assert.equal(formatRow({label: '', amount: -0}), ': 0');
assert.equal(formatRow({label: 'large', amount: 1e21}), 'large: 1e+21');
assert.equal(formatRow({label: 'small', amount: 1e-7}), 'small: 1e-7');

const first = buildReport(rows);
const second = buildReport(rows);
assert.notStrictEqual(first, second);
assert.notStrictEqual(first.lines, second.lines);
first.title = 'Changed';
first.lines.push('extra');
assert.deepEqual(second, {
  title: 'Report',
  count: 3,
  total: 10,
  lines: ['credit: 12.5', ': 0', 'credit: -2.5'],
});
const emptyFirst = buildReport([]);
const emptySecond = buildReport([]);
assert.notStrictEqual(emptyFirst, emptySecond);
assert.notStrictEqual(emptyFirst.lines, emptySecond.lines);

const mutableRows = [{label: 'original', amount: 3}];
const snapshot = buildReport(mutableRows);
mutableRows[0].label = 'changed';
mutableRows[0].amount = 9;
mutableRows.push({label: 'later', amount: 1});
assert.deepEqual(snapshot, {
  title: 'Report', count: 1, total: 3, lines: ['original: 3'],
});

