exports.loadSettings = async (path, read = require('node:fs/promises').readFile) => {
  let contents;
  try {
    contents = await read(path, 'utf8');
  } catch (error) {
    if (error?.code === 'ENOENT') return {enabled: true, limit: 10};
    throw error;
  }
  const {enabled = true, limit = 10} = JSON.parse(contents);
  return {enabled, limit};
};

