const assert = require('node:assert/strict');
const {test} = require('node:test');
const {mkdtemp, writeFile, rm} = require('node:fs/promises');
const {join} = require('node:path');
const {spawnSync} = require('node:child_process');
const {loadSettings} = require('./settings.cjs');

test('reads once with utf8 and defaults only omitted fields', async () => {
  for (const settings of [{}, {enabled: false, limit: 0}, {enabled: null, limit: ''}, {enabled: true, limit: 4}]) {
    const calls = [];
    const result = await loadSettings('settings.json', async (...args) => {
      calls.push(args);
      return JSON.stringify(settings);
    });
    assert.deepEqual(calls, [['settings.json', 'utf8']]);
    assert.deepEqual(result, {
      enabled: settings.enabled === undefined ? true : settings.enabled,
      limit: settings.limit === undefined ? 10 : settings.limit,
    });
  }
});

test('only missing reads recover; other read errors keep identity', async () => {
  assert.deepEqual(await loadSettings('missing', async () => {
    throw Object.assign(new Error('missing'), {code: 'ENOENT'});
  }), {enabled: true, limit: 10});
  for (const error of [Object.assign(new Error('denied'), {code: 'EACCES'}), Object.assign(new Error('directory'), {code: 'EISDIR'}), new Error('read failed'), null, undefined, false]) {
    await assert.rejects(loadSettings('bad', async () => { throw error; }), actual => actual === error);
  }
});

test('parse errors propagate unchanged even with a missing-file code', async () => {
  const parse = JSON.parse;
  const error = Object.assign(new SyntaxError('invalid JSON'), {code: 'ENOENT'});
  JSON.parse = () => { throw error; };
  try {
    await assert.rejects(loadSettings('bad', async () => '{'), actual => actual === error);
  } finally {
    JSON.parse = parse;
  }
});

test('CLI emits exactly one report or only an error', async () => {
  const directory = await mkdtemp(join(__dirname, 'settings-report-'));
  try {
    const valid = join(directory, 'valid.json');
    const malformed = join(directory, 'bad.json');
    await writeFile(valid, '{"enabled":false,"limit":0}');
    await writeFile(malformed, '{');
    for (const [path, expected] of [[valid, {enabled: false, limit: 0}], [join(directory, 'missing'), {enabled: true, limit: 10}]]) {
      const result = spawnSync(process.execPath, [join(__dirname, 'cli.cjs'), path], {encoding: 'utf8'});
      assert.equal(result.status, 0);
      assert.equal(result.stdout, JSON.stringify(expected) + '\n');
      assert.equal(result.stderr, '');
    }
    for (const path of [malformed, directory]) {
      const result = spawnSync(process.execPath, [join(__dirname, 'cli.cjs'), path], {encoding: 'utf8'});
      assert.notEqual(result.status, 0);
      assert.equal(result.stdout, '');
      let error;
      try { await loadSettings(path); } catch (caught) { error = caught; }
      assert.ok(error);
      assert.equal(result.stderr, error.message + '\n');
    }
  } finally {
    await rm(directory, {recursive: true, force: true});
  }
});

