exports.loadSettings = async (path, read = require('node:fs/promises').readFile) => {
  let source;
  try {
    source = await read(path, 'utf8');
  } catch (error) {
    if (error?.code !== 'ENOENT') throw error;
    return {enabled: true, limit: 10};
  }
  const {enabled = true, limit = 10} = JSON.parse(source);
  return {enabled, limit};
};

