const assert = require('node:assert/strict');
const {test} = require('node:test');
const {mkdtemp, writeFile, rm} = require('node:fs/promises');
const {join} = require('node:path');
const {spawnSync} = require('node:child_process');
const {loadSettings} = require('./settings.cjs');

test('uses defaults only for omitted properties and reads once with utf8', async () => {
  for (const [source, expected] of [
    ['{}', {enabled: true, limit: 10}],
    ['{"enabled":false,"limit":0}', {enabled: false, limit: 0}],
    ['{"enabled":null,"limit":""}', {enabled: null, limit: ''}],
    ['{"enabled":false}', {enabled: false, limit: 10}],
    ['{"limit":4}', {enabled: true, limit: 4}],
  ]) {
    const calls = [];
    assert.deepEqual(await loadSettings('settings.json', async (...args) => {
      calls.push(args);
      return source;
    }), expected);
    assert.deepEqual(calls, [['settings.json', 'utf8']]);
  }
});

test('only missing read errors use defaults; other errors retain identity', async () => {
  const missing = Object.assign(new Error('missing'), {code: 'ENOENT'});
  assert.deepEqual(await loadSettings('missing', async () => { throw missing; }), {enabled: true, limit: 10});
  for (const error of [Object.assign(new Error('denied'), {code: 'EACCES'}), new Error('read failed')]) {
    await assert.rejects(loadSettings('settings', async () => { throw error; }), actual => actual === error);
  }
});

test('propagates the original JSON parse error', async () => {
  const originalParse = JSON.parse;
  const error = new SyntaxError('parse failed');
  JSON.parse = () => { throw error; };
  try {
    await assert.rejects(loadSettings('settings', async () => '{}'), actual => actual === error);
  } finally {
    JSON.parse = originalParse;
  }
  await assert.rejects(loadSettings('settings', async () => '{'), SyntaxError);
});

test('CLI reports settings and missing defaults, and fails without stdout on parse/read errors', async () => {
  const directory = await mkdtemp(join(__dirname, '.settings-report-'));
  try {
    const settings = join(directory, 'settings.json');
    await writeFile(settings, '{"enabled":false,"limit":0}');
    const malformed = join(directory, 'malformed.json');
    await writeFile(malformed, '{');
    for (const [path, expected] of [
      [settings, '{"enabled":false,"limit":0}\n'],
      [join(directory, 'missing.json'), '{"enabled":true,"limit":10}\n'],
    ]) {
      const result = spawnSync(process.execPath, [join(__dirname, 'cli.cjs'), path], {encoding: 'utf8'});
      assert.equal(result.status, 0);
      assert.equal(result.stdout, expected);
      assert.equal(result.stderr, '');
    }
    for (const path of [malformed, directory]) {
      const result = spawnSync(process.execPath, [join(__dirname, 'cli.cjs'), path], {encoding: 'utf8'});
      assert.equal(result.status, 1);
      assert.equal(result.stdout, '');
      assert.notEqual(result.stderr.trim(), '');
    }
  } finally {
    await rm(directory, {recursive: true, force: true});
  }
});

