const assert = require('node:assert/strict');
const {test} = require('node:test');
const {mkdtemp, writeFile, rm} = require('node:fs/promises');
const {tmpdir} = require('node:os');
const {join} = require('node:path');
const {spawnSync} = require('node:child_process');
const {loadSettings} = require('./settings.cjs');

test('defaults only omitted settings and calls read once with utf8', async () => {
  for (const [input, expected] of [
    ['{}', {enabled: true, limit: 10}],
    ['{"enabled":false,"limit":0}', {enabled: false, limit: 0}],
    ['{"enabled":null,"limit":""}', {enabled: null, limit: ''}],
    ['{"enabled":true,"limit":25}', {enabled: true, limit: 25}],
  ]) {
    const calls = [];
    const result = loadSettings('settings.json', async (...args) => {
      calls.push(args);
      return input;
    });
    assert.ok(result instanceof Promise);
    assert.deepEqual(await result, expected);
    assert.deepEqual(calls, [['settings.json', 'utf8']]);
  }
});

test('recovers missing reads but preserves other original errors', async () => {
  const missing = Object.assign(new Error('missing'), {code: 'ENOENT'});
  assert.deepEqual(await loadSettings('missing', async () => { throw missing; }),
    {enabled: true, limit: 10});
  for (const error of [Object.assign(new Error('denied'), {code: 'EACCES'}), new Error('read failed')]) {
    await assert.rejects(loadSettings('file', async () => { throw error; }), actual => actual === error);
  }
  await assert.rejects(loadSettings('file', async () => '{'), SyntaxError);
});

test('CLI reports valid and missing files; failures produce only stderr', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'settings-test-'));
  try {
    const file = join(directory, 'settings.json');
    await writeFile(file, '{"enabled":false,"limit":0}');
    let result = spawnSync(process.execPath, [join(__dirname, 'cli.cjs'), file], {encoding: 'utf8'});
    assert.equal(result.status, 0);
    assert.equal(result.stdout, '{"enabled":false,"limit":0}\n');
    assert.equal(result.stderr, '');
    result = spawnSync(process.execPath, [join(__dirname, 'cli.cjs'), join(directory, 'missing')], {encoding: 'utf8'});
    assert.equal(result.status, 0);
    assert.equal(result.stdout, '{"enabled":true,"limit":10}\n');
    assert.equal(result.stderr, '');
    await writeFile(file, '{');
    for (const path of [file, directory]) {
      result = spawnSync(process.execPath, [join(__dirname, 'cli.cjs'), path], {encoding: 'utf8'});
      assert.notEqual(result.status, 0);
      assert.equal(result.stdout, '');
      assert.ok(result.stderr.trim());
    }
  } finally {
    await rm(directory, {recursive: true, force: true});
  }
});

