const assert = require('node:assert/strict');
const {mkdtemp, writeFile, rm} = require('node:fs/promises');
const {join} = require('node:path');
const {spawnSync} = require('node:child_process');
const {loadSettings} = require('./settings.cjs');

(async () => {
  for (const [source, expected] of [
    ['{}', {enabled: true, limit: 10}],
    ['{"enabled":false,"limit":0}', {enabled: false, limit: 0}],
    ['{"enabled":null,"limit":""}', {enabled: null, limit: ''}],
    ['{"enabled":true,"limit":25}', {enabled: true, limit: 25}],
  ]) {
    let calls = 0;
    assert.deepEqual(await loadSettings('settings.json', async (...args) => {
      calls++;
      assert.deepEqual(args, ['settings.json', 'utf8']);
      return source;
    }), expected);
    assert.equal(calls, 1);
  }
  assert.deepEqual(await loadSettings('missing', async () => {
    throw Object.assign(new Error('missing'), {code: 'ENOENT'});
  }), {enabled: true, limit: 10});
  for (const code of ['EACCES', 'EISDIR', undefined]) {
    const error = Object.assign(new Error('read failed'), {code});
    await assert.rejects(loadSettings('bad', async () => { throw error; }), actual => actual === error);
  }
  await assert.rejects(loadSettings('bad', async () => '{'), SyntaxError);

  const directory = await mkdtemp(join(__dirname, 'settings-report-'));
  try {
    for (const [name, source, expected] of [
      ['defaults.json', '{}', {enabled: true, limit: 10}],
      ['explicit.json', '{"enabled":false,"limit":0}', {enabled: false, limit: 0}],
      ['missing.json', undefined, {enabled: true, limit: 10}],
      ['broken.json', '{', undefined],
    ]) {
      const path = join(directory, name);
      if (source !== undefined) await writeFile(path, source);
      const result = spawnSync(process.execPath, [join(__dirname, 'cli.cjs'), path], {encoding: 'utf8'});
      if (expected) {
        assert.equal(result.status, 0);
        assert.equal(result.stdout, JSON.stringify(expected) + '\n');
        assert.equal(result.stderr, '');
      } else {
        assert.notEqual(result.status, 0);
        assert.equal(result.stdout, '');
        assert.match(result.stderr, /JSON/);
      }
    }
    const result = spawnSync(process.execPath, [join(__dirname, 'cli.cjs'), directory], {encoding: 'utf8'});
    assert.notEqual(result.status, 0);
    assert.equal(result.stdout, '');
    assert.match(result.stderr, /EISDIR/);
  } finally {
    await rm(directory, {recursive: true, force: true});
  }
})().catch(error => {
  console.error(error);
  process.exitCode = 1;
});

