const assert = require('node:assert/strict');
const {execFileSync} = require('node:child_process');
const {createBasket} = require('./basket.cjs');

const initial = [{sku: 'tea', price: 250, quantity: 2}];
const basket = createBasket(initial);
initial[0].quantity = 99;
initial.push({sku: 'ignored', price: 1, quantity: 1});
assert.deepEqual(basket.receipt(), {
  items: [{sku: 'tea', price: 250, quantity: 2}], count: 2, total: 500,
});

basket.set('cake', 400, 1);
const snapshot = basket.receipt();
basket.set('tea', 100, 3);
assert.deepEqual(basket.receipt(), {
  items: [{sku: 'tea', price: 100, quantity: 3}, {sku: 'cake', price: 400, quantity: 1}],
  count: 4, total: 700,
});
assert.equal(basket.count, 4);
assert.equal(basket.total, 700);
assert.deepEqual(snapshot, {
  items: [{sku: 'tea', price: 250, quantity: 2}, {sku: 'cake', price: 400, quantity: 1}],
  count: 3, total: 900,
});
snapshot.items[0].quantity = 99;
snapshot.items.push({sku: 'ignored', price: 1, quantity: 1});
assert.equal(basket.count, 4);
assert.equal(basket.receipt().items.length, 2);
basket.remove('missing');
assert.equal(basket.total, 700);
basket.remove('tea');
assert.deepEqual(basket.receipt(), {items: [{sku: 'cake', price: 400, quantity: 1}], count: 1, total: 400});
basket.set('tea', 0, 2);
assert.deepEqual(basket.receipt().items.map(row => row.sku), ['cake', 'tea']);
assert.equal(basket.count, 3);
assert.equal(basket.total, 400);

const replacement = [{sku: '__proto__', price: 0, quantity: 5}];
basket.reset(replacement);
replacement[0].quantity = 99;
replacement.length = 0;
assert.deepEqual(basket.receipt(), {items: [{sku: '__proto__', price: 0, quantity: 5}], count: 5, total: 0});
const independent = createBasket();
independent.set('other', 20, 2);
basket.reset();
assert.deepEqual(basket.receipt(), {items: [], count: 0, total: 0});
assert.deepEqual(independent.receipt(), {items: [{sku: 'other', price: 20, quantity: 2}], count: 2, total: 40});
assert.deepEqual(JSON.parse(execFileSync(process.execPath, ['demo.cjs'], {cwd: __dirname, encoding: 'utf8'})), {
  items: [{sku: 'tea', price: 250, quantity: 2}, {sku: 'cake', price: 400, quantity: 1}], count: 3, total: 900,
});

