const assert = require('node:assert/strict');
const {test} = require('node:test');
const {saveDraft} = require('./service.cjs');
const {createStore} = require('./store.cjs');

const outcomes = ['return', 'resolve', 'throw', 'reject'];

for (const writeOutcome of outcomes) {
  for (const auditOutcome of outcomes) {
    test(`write ${writeOutcome}, audit ${auditOutcome}`, async () => {
      const draft = {id:'draft-1'};
      const result = {stored:true};
      const writeError = undefined;
      const auditError = {message:'audit failed'};
      const calls = [];
      const writeFails = ['throw', 'reject'].includes(writeOutcome);
      const auditFails = ['throw', 'reject'].includes(auditOutcome);
      const saving = saveDraft(draft, {
        store: {write(received) {
          assert.equal(received, draft);
          calls.push('write');
          if (writeOutcome === 'throw') throw writeError;
          if (writeOutcome === 'reject') return Promise.reject(writeError);
          return writeOutcome === 'resolve' ? Promise.resolve(result) : result;
        }},
        audit(event) {
          calls.push(event);
          if (auditOutcome === 'throw') throw auditError;
          if (auditOutcome === 'reject') return Promise.reject(auditError);
          return auditOutcome === 'resolve' ? Promise.resolve() : undefined;
        },
      });
      if (writeFails || auditFails) {
        await assert.rejects(saving, error => error === (auditFails ? auditError : writeError));
      } else {
        assert.equal(await saving, result);
      }
      assert.deepEqual(calls, ['write', {type:writeFails ? 'failed' : 'saved', id:draft.id}]);
    });
  }
}

for (const fails of [false, true]) {
  test(`awaits ${fails ? 'failed' : 'saved'} audit`, async () => {
    let finishAudit;
    const auditPending = new Promise(resolve => { finishAudit = resolve; });
    const writeError = new Error('write failed');
    let settled = false;
    const saving = saveDraft({id:'draft-2'}, {
      store: {write() { if (fails) throw writeError; return 'stored'; }},
      audit: () => auditPending,
    });
    const settlement = saving.then(() => { settled = true; }, () => { settled = true; });
    await new Promise(resolve => setImmediate(resolve));
    assert.equal(settled, false);
    finishAudit();
    if (fails) await assert.rejects(saving, error => error === writeError);
    else assert.equal(await saving, 'stored');
    await settlement;
  });
}

test('store writes serialized draft and returns id after completion', async () => {
  const draft = {id:'draft-3', text:'hello'};
  let finishWrite;
  const pending = new Promise(resolve => { finishWrite = resolve; });
  const calls = [];
  const store = createStore((...args) => { calls.push(args); return pending; });
  let settled = false;
  const writing = store.write(draft);
  writing.then(() => { settled = true; });
  await new Promise(resolve => setImmediate(resolve));
  assert.equal(settled, false);
  assert.deepEqual(calls, [['draft-3.json', JSON.stringify(draft), 'utf8']]);
  finishWrite('ignored');
  assert.equal(await writing, draft.id);
});

for (const outcome of outcomes) {
  test(`store writeFile ${outcome}`, async () => {
    const error = new Error('disk failed');
    const store = createStore(() => {
      if (outcome === 'throw') throw error;
      if (outcome === 'reject') return Promise.reject(error);
      return outcome === 'resolve' ? Promise.resolve('ignored') : 'ignored';
    });
    if (['throw', 'reject'].includes(outcome)) {
      await assert.rejects(store.write({id:'draft-4'}), received => received === error);
    } else {
      assert.equal(await store.write({id:'draft-4'}), 'draft-4');
    }
  });
}

